import{_ as l,l as s,o as a,c as o,v as r,p as c,x as t,d as n,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"定时器轮","description":"","frontmatter":{"title":"定时器轮","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/timer-wheel.md","filePath":"cs/timer-wheel.md","lastUpdated":1789023840000}'),p={name:"cs/timer-wheel.md"};function m(_,e,E,u,f,T){const i=s("Mermaid");return a(),o("div",null,[e[1]||(e[1]=r('<h1 id="定时器轮" tabindex="-1">定时器轮 <a class="header-anchor" href="#定时器轮" aria-label="Permalink to &quot;定时器轮&quot;">​</a></h1><div class="epigraph"><p>timer wheel 用分层环把超时时间哈希到槽：O(1) 插入/删除，到期精度与槽宽成反比，适合海量不精确超时。</p><footer>—— 据 Varghese and Lauck 对 hashed timing wheels 的经典论述；Linux timer wheel 文档</footer></div><p><a href="/cs/tickless-nohz">tickless</a> 减少了谁来推轮。<a href="/cs/kernel-tcp-impl">TCP</a> 的 RTO、<a href="/cs/napi">NAPI</a> 无关但网络栈大量用超时。缺口是 <strong>内核定时器轮</strong> vs hrtimer 红黑树。调度进阶在此收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>百万连接不能每人一棵精确树。wheel：时间模槽数，级联到更粗层。缺口：向前推进可能 cascade 成本；不适合亚微秒；hrtimer 给高精度（DL、nanosleep）。本课不把 cascade 代码写成作业。</p><p><span class="marginnote">jiffies 是轮的经典单位。NO_HZ 下推进发生在必要时。对象是超时集合，不是 RTC 芯片。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>add_timer</code>：算槽，挂链表。tick/hrtimer 回调：处理当前槽，cascade。对照 qdisc：一个按包整形，一个按时间触发函数。对照 <a href="/cs/slab-allocator">slab</a>：都是内核基础设施。对照用户 timerfd：底层仍可能是 hrtimer。</p>',8)),(a(),c(d,null,{default:t(()=>[h(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADD%5B%22add_timer%22%5D%20--%3E%20SLOT%5B%22%E5%93%88%E5%B8%8C%E5%88%B0%E6%A7%BD%22%5D%0A%20%20TICK%5B%22%E6%97%B6%E9%97%B4%E6%8E%A8%E8%BF%9B%22%5D%20--%3E%20FIRE%5B%22%E5%88%B0%E6%9C%9F%E5%9B%9E%E8%B0%83%22%5D%0A%20%20SLOT%20--%3E%20CASC%5B%22%E6%BA%A2%E5%87%BA%E7%BA%A7%E8%81%94%E5%88%B0%E7%B2%97%E5%B1%82%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>wheel 用精度换规模，使 TCP、邻项、工作队列能活。高精度路径走 hrtimer，避免污染轮。不要写成编译器哈希课。与 <a href="/cs/preempt-rt">PREEMPT_RT</a>：回调上下文是否可睡决定用哪种定时器。</p><p>错误的长时间 cascade 会造成延迟尖峰，这是测量时要看到的。</p><p>实现上：cascade 在跨过粗层边界时可能一次处理很多定时器，造成延迟尖峰。hrtimer 走红黑树，给 nanosleep 和 DL。NO_HZ 下轮子在进入空闲时才推到「现在」。 读法上只引用<a href="/cs/tickless-nohz">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>定时器轮</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 alarmtimer 的全部时钟基础。不保证用户 POSIX 定时器精度等于 wheel。下一单元安全与启动：Linux capabilities。</p><p>版本字段会变，课序钉的是机制对象「定时器轮」，不是某一主线内核的结构体名。 后课默认：海量超时走 timer wheel，精确事件走 hrtimer。进程权能如何切分 root，下一课 capabilities。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>timer wheel：O(1) 粗粒度超时。</li><li>hrtimer 服务高精度；tickless 改变谁推轮。</li><li>capabilities 是下一单元。</li><li>出处：Varghese and Lauck；Linux timers。</li></ul>',11))])}const k=l(p,[["render",m]]);export{A as __pageData,k as default};
